function setAttachChk(div, val) {
    /* sdd-asis-lifecycle:begin fn_setAttach_chk — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fm = (document.SendForm || { elements: [] });
    const bf_file_cnt = parseInt($c.util.getComponent("ipt_fileSaveCnt").getValue());
    const af_file_cnt = parseInt($c.util.getComponent("ipt_fileRowNum").getValue()) - bf_file_cnt;
    if (af_file_cnt == 1) {
        fm.attach_file_tp_cd.value = val;
    } else {
        fm.attach_file_tp_cd[div].value = val;
    }
    /* sdd-asis-lifecycle:end */
}

/**
 * @method
 * @name scwin.clickCreditValuInstCd
 * @author Inswave
 * @date 2026. 09. 29
 * @param inst_cd type frm obj
 * @returns
 * @hidden N
*/
scwin.clickCreditValuInstCd = function (inst_cd, type, frm, obj) {
    /* sdd-asis-lifecycle:begin fn_click_credit_valu_inst_cd — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fm = (document.SendForm || { elements: [] });
    if (obj.checked) {
        $c.util.getComponent("frm.credit_valu_inst_cd" + type).setValue(inst_cd);
        eval("frm.byinst_credit_valu_grd" + type).disabled = false;
        eval("frm.sf_valu_yn" + type).disabled = true;
        $c.util.getComponent("frm.sf_valu_yn" + type).checked = false;
    } else {
        $c.util.getComponent("frm.credit_valu_inst_cd" + type).setValue('');
        $c.util.getComponent("frm.byinst_credit_valu_grd" + type).setValue('');
        eval("frm.byinst_credit_valu_grd" + type).disabled = true;
        eval("frm.sf_valu_yn" + type).disabled = true;
        $c.util.getComponent("frm.sf_valu_yn" + type).checked = false;
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setRedmptDd
 * @author Inswave
 * @date 2026. 09. 29
 * @param obj addYy
 * @returns
 * @hidden N
*/
scwin.setRedmptDd = async function (obj, addYy) {
    /* sdd-asis-lifecycle:begin fn_setRedmptDd — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const isuDd = Del_Hypen2(obj);
    const fm = (document.SendForm || { elements: [] });
    if (isuDd == null || isuDd === "") {
        await $c.win.alert("발행일을 입력하시기 바랍니다.");
        $c.util.getComponent("cal_isuDd").focus();
        return;
    }
    const tmpYy = isuDd.substr(0, 4);
    const tmpMm = isuDd.substr(4, 2);
    const tmpDd = isuDd.substr(6, 2);
    const redmptYy = parseInt(tmpYy) + parseInt(addYy);
    mmCnt = new Array(12);
    mmCnt[1] = '31';
    mmCnt[3] = '31';
    mmCnt[4] = '30';
    mmCnt[5] = '31';
    mmCnt[6] = '30';
    mmCnt[7] = '31';
    mmCnt[8] = '31';
    mmCnt[9] = '30';
    mmCnt[10] = '31';
    mmCnt[11] = '30';
    mmCnt[12] = '31';
    if (scwin.isYunMonth(redmptYy)) {
        mmCnt[2] = '29';
    } else {
        mmCnt[2] = '28';
    }
    if (parseInt(tmpDd, 10) < mmCnt[parseInt(tmpMm,10)]) {
        $c.util.getComponent("cal_redmptDd").setValue(redmptYy + "-" + tmpMm + "-" + tmpDd);
    } else {
        $c.util.getComponent("cal_redmptDd").setValue(redmptYy + "-" + tmpMm + "-" + mmCnt[parseInt(tmpMm,10)]);
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.isYunMonth
 * @author Inswave
 * @date 2026. 09. 29
 * @param strYear
 * @returns
 * @hidden N
*/
scwin.isYunMonth = function (strYear) {
    /* sdd-asis-lifecycle:begin isYunMonth — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    nYear = parseInt(strYear);
    if ((nYear % 4) == 0) {
        return true;
    } else {
        return false;
    }
    /* sdd-asis-lifecycle:end */
};


